// CheckAndSetDefaults is a helper returns an error if the supplied configuration
// is not enough to connect to DynamoDB
func (cfg *Config) CheckAndSetDefaults() error {
	// Table name is required.
	if cfg.TableName == "" {
		return trace.BadParameter("DynamoDB: table_name is not specified")
	}
	if cfg.BillingMode == "" {
		cfg.BillingMode = billingModePayPerRequest
	}
	if cfg.BillingMode != billingModePayPerRequest && cfg.BillingMode != billingModeProvisioned {
		return trace.BadParameter("DynamoDB: invalid billing_mode %q (expected %q or %q)", cfg.BillingMode, billingModePayPerRequest, billingModeProvisioned)
